(() => {
  const SCH = { О: 'Ограждение', В: 'Вызов', П: 'Прорицание', Ч: 'Очарование', Э: 'Воплощение', И: 'Иллюзия', Н: 'Некромантия', Т: 'Преобразование' };
  const CLS = { Б: 'Бард', Вл: 'Волшебник', Д: 'Друид', Ж: 'Жрец', К: 'Колдун', П: 'Паладин', С: 'Следопыт', Ч: 'Чародей' };
  const time = (t) => ({ a: '1 действие', b: '1 бонусное действие', r: '1 реакция' }[t] || t);
  const range = (r) => (r === 'к' ? 'Касание' : r === 'с' ? 'На себя' : r === '∞' ? 'Неограниченная' : /^\d+$/.test(r) ? `${r} фт` : r);
  const word = (n, u) => {
    if (u === 'r') return n === 1 ? '1 раунд' : `${n} раундов`;
    if (u === 'm') return n === 1 ? '1 минута' : `${n} минут`;
    if (u === 'h') return n === 1 ? '1 час' : n < 5 ? `${n} часа` : `${n} часов`;
    return n === 1 ? '1 день' : n < 5 ? `${n} дня` : `${n} дней`;
  };
  const dur = (d) => {
    if (d === 'i') return 'Мгновенная';
    if (d === 'd') return 'До рассеивания';
    const m = d.match(/^(c)?(\d+)([rmhd])$/);
    if (!m) return d;
    const n = +m[2], u = m[3];
    if (m[1]) return `Концентрация, до ${u === 'm' ? (n === 1 ? '1 минуты' : `${n} минут`) : u === 'h' ? (n === 1 ? '1 часа' : `${n} часов`) : u === 'r' ? `${n} раундов` : `${n} дней`}`;
    return word(n, u);
  };
  const have = new Set(SPELLS.map((s) => s.e));
  SPELLS_EXTRA.forEach((row) => {
    const [n, e, lv, s, t, r, c, d, k, f, u, x] = row.split('|');
    if (have.has(e)) return;
    const l = parseInt(lv);
    SPELLS.push({
      n, e, l, s: SCH[s] || s, t: time(t), r: range(r), c: c.split('').join(', '), d: dur(d),
      k: k.split(',').map((z) => CLS[z] || z).join(', '), x,
      ...(f ? { f } : {}), ...(u ? { u } : {}),
      ...(d.startsWith('c') ? { cn: true } : {}), ...(lv.includes('r') ? { rt: true } : {}), ...(lv.includes('m') ? { addMod: true } : {}),
    });
  });
  SPELLS.sort((a, b) => a.l - b.l || a.n.localeCompare(b.n, 'ru'));
})();
const spellByE = (e) => SPELLS.find((s) => s.e === e);
